import { createHash, randomBytes, scryptSync, timingSafeEqual } from "node:crypto";
import type { IncomingMessage, ServerResponse } from "node:http";
import { config } from "./config.js";
import { readJson, writeJson } from "./store.js";

// One owner, one passphrase. The passphrase is generated by `./homestead client` and shown
// once in your terminal; only its scrypt hash is stored here. Sessions are random tokens in
// an HttpOnly, SameSite=Strict cookie; we store only their SHA-256.

interface PasswordFile {
  salt: string;
  hash: string;
}

const AUTH_FILE = "auth.json";
const SESSIONS_FILE = "sessions.json";
const SESSION_DAYS = 30;
const COOKIE = "homestead_session";

export function setPassword(password: string): void {
  if (password.length < 12) throw new Error("passphrase must be at least 12 characters");
  const salt = randomBytes(16);
  const hash = scryptSync(password, salt, 32);
  writeJson(AUTH_FILE, { salt: salt.toString("hex"), hash: hash.toString("hex") } satisfies PasswordFile);
}

export function hasPassword(): boolean {
  return readJson<PasswordFile | null>(AUTH_FILE, null) !== null;
}

function checkPassword(password: string): boolean {
  const stored = readJson<PasswordFile | null>(AUTH_FILE, null);
  if (!stored) return false;
  const actual = scryptSync(password, Buffer.from(stored.salt, "hex"), 32);
  return timingSafeEqual(actual, Buffer.from(stored.hash, "hex"));
}

const sha256 = (token: string) => createHash("sha256").update(token).digest("hex");
let sessions = new Map<string, number>(Object.entries(readJson<Record<string, number>>(SESSIONS_FILE, {})));

function saveSessions(): void {
  const now = Date.now();
  sessions = new Map([...sessions].filter(([, expires]) => expires > now));
  writeJson(SESSIONS_FILE, Object.fromEntries(sessions));
}

function cookieValue(req: IncomingMessage): string | undefined {
  const header = req.headers.cookie ?? "";
  for (const part of header.split(";")) {
    const [name, ...rest] = part.trim().split("=");
    if (name === COOKIE) return rest.join("=");
  }
  return undefined;
}

export function isLoggedIn(req: IncomingMessage): boolean {
  if (config.demo) return true;
  const token = cookieValue(req);
  if (!token) return false;
  const expires = sessions.get(sha256(token));
  return expires !== undefined && expires > Date.now();
}

// Simple per-IP throttle: 10 attempts per 10 minutes.
const attempts = new Map<string, number[]>();

export function login(req: IncomingMessage, res: ServerResponse, password: string): boolean {
  const ip = String(req.headers["x-forwarded-for"] ?? req.socket.remoteAddress ?? "?").split(",")[0]!.trim();
  const now = Date.now();
  const recent = (attempts.get(ip) ?? []).filter((t) => now - t < 10 * 60 * 1000);
  if (recent.length >= 10) return false;
  recent.push(now);
  attempts.set(ip, recent);
  if (!checkPassword(password)) return false;

  attempts.delete(ip);
  const token = randomBytes(32).toString("base64url");
  sessions.set(sha256(token), now + SESSION_DAYS * 24 * 3600 * 1000);
  saveSessions();
  res.setHeader("Set-Cookie", sessionCookie(token, SESSION_DAYS * 24 * 3600));
  return true;
}

export function logout(req: IncomingMessage, res: ServerResponse): void {
  const token = cookieValue(req);
  if (token) {
    sessions.delete(sha256(token));
    saveSessions();
  }
  res.setHeader("Set-Cookie", sessionCookie("", 0));
}

function sessionCookie(value: string, maxAge: number): string {
  const secure = config.secureCookies ? "; Secure" : "";
  return `${COOKIE}=${value}; Path=/; HttpOnly; SameSite=Strict; Max-Age=${maxAge}${secure}`;
}
